          continue
          ;;
      esac
    fi
    case "${COMP_WORDS[$i]}" in
      imports)
        _pkl_analyze_imports $(( i + 1 ))
        return
        ;;
      *)
        (( i = i + 1 ))
        # drop the head of the array
        fixed_arg_names=("${fixed_arg_names[@]:1}")
